const ORDER=['es','co','pe','ec','bo','ve','ar','cl','mx','gt','hn','sv','ni','cr','pa','do','cu'];

function entryText(c){
  if(c.eu) return T(c.entry);
  const base=c.visa==='need'
    ?['Para una visita corta necesitas visa Schengen. Para vivir en Suiza necesitas una visa nacional D, que solo se emite cuando el cantón ha aprobado tu permiso.','Pour une visite courte, il te faut un visa Schengen. Pour vivre en Suisse, il te faut un visa national D, délivré seulement une fois que le canton a approuvé ton permis.']
    :['Puedes visitar Suiza sin visa hasta 90 días en 180. Para vivir aquí necesitas una visa nacional D, que solo se emite cuando el cantón ha aprobado tu permiso.','Tu peux visiter la Suisse sans visa jusqu\'à 90 jours sur 180. Pour y vivre, il te faut un visa national D, délivré seulement une fois que le canton a approuvé ton permis.'];
  const et=c.visa==='free'?T([' El ETIAS (autorización de viaje) todavía no funciona: la UE anunciará la fecha con meses de antelación.',' L\'ETIAS (autorisation de voyage) ne fonctionne pas encore : l\'UE annoncera la date plusieurs mois à l\'avance.']):'';
  return T(base)+et;
}

/* ---------- guides ---------- */
const G={
 apostilla:{t:['La apostilla, explicada','L\'apostille, expliquée'],d:['Qué es, quién la pone y por qué Suiza la pide.','Ce que c\'est, qui la délivre et pourquoi la Suisse l\'exige.'],
  body:[`<p>La apostilla es un sello o certificado que el <b>país que emitió el documento</b> añade para confirmar que la firma y el cargo del funcionario son auténticos. No dice nada sobre el contenido: solo prueba que el documento es oficial.</p>
<h2>¿Quién la pone?</h2><p>Siempre una autoridad de tu país (casi siempre el Ministerio de Relaciones Exteriores o Cancillería). Ni la embajada suiza ni los consulados de tu país en Suiza apostillan documentos.</p>
<h2>¿Qué países la usan?</h2><p>España y todos los países latinoamericanos de esta guía forman parte del Convenio de La Haya, <b>salvo Cuba</b>. Para Cuba hace falta una cadena de legalizaciones (ministerios cubanos y después la representación suiza).</p>
<div class="callout">El orden correcto es: <b>1.</b> pedir el documento, <b>2.</b> apostillarlo en tu país, <b>3.</b> traducirlo en Suiza si no está en francés, alemán, italiano o inglés. Una traducción hecha antes de la apostilla no traduce la apostilla.</div>
<h2>Apostilla electrónica</h2><p>Colombia, Perú, Chile, Venezuela, Argentina, México y República Dominicana ofrecen apostillas en línea para algunos documentos. Llevan un código para verificarlas en Internet. Consulta la ficha de tu país.</p>`,
`<p>L\'apostille est un cachet ou un certificat que le <b>pays qui a émis le document</b> ajoute pour confirmer que la signature et la fonction du fonctionnaire sont authentiques. Elle ne dit rien du contenu : elle prouve seulement que le document est officiel.</p>
<h2>Qui la délivre ?</h2><p>Toujours une autorité de ton pays (presque toujours le ministère des Affaires étrangères). Ni l\'ambassade de Suisse ni les consulats de ton pays en Suisse n\'apostillent les documents.</p>
<h2>Quels pays l\'utilisent ?</h2><p>L\'Espagne et tous les pays latino-américains de ce guide font partie de la Convention de La Haye, <b>sauf Cuba</b>. Pour Cuba, il faut une chaîne de légalisations (ministères cubains puis représentation suisse).</p>
<div class="callout">Le bon ordre : <b>1.</b> demander le document, <b>2.</b> le faire apostiller dans ton pays, <b>3.</b> le faire traduire en Suisse s\'il n\'est pas en français, allemand, italien ou anglais. Une traduction faite avant l\'apostille ne traduit pas l\'apostille.</div>
<h2>Apostille électronique</h2><p>La Colombie, le Pérou, le Chili, le Venezuela, l\'Argentine, le Mexique et la République dominicaine proposent des apostilles en ligne pour certains documents. Elles portent un code vérifiable sur Internet. Consulte la fiche de ton pays.</p>`],
  src:[['HCCH · Convenio Apostilla',OFF.hcch]]},
 traduccion:{t:['Traducir tus documentos en Suiza','Traduire tes documents en Suisse'],d:['Cuándo hace falta una traducción oficial y cómo evitarla.','Quand une traduction officielle est nécessaire et comment l\'éviter.'],
  body:[`<p>Las autoridades suizas aceptan documentos en una lengua nacional (francés, alemán, italiano) o en inglés. <b>Un documento en español debe ir acompañado de una traducción oficial.</b></p>
<h2>¿Quién traduce?</h2><p>Un traductor jurado u oficial reconocido. En Suiza romanda, la traducción suele hacerse al francés. Pregunta a la oficina que recibirá tu expediente si exige que la firma del traductor esté legalizada.</p>
<h2>Cómo ahorrar</h2><ul><li>España emite certificados plurilingües (modelo internacional): las oficinas suizas no exigen traducir los documentos internacionales.</li><li>Traduce también la apostilla, en el mismo encargo.</li><li>Pide primero la lista exacta: no traduzcas documentos que nadie te pidió.</li></ul>`,
`<p>Les autorités suisses acceptent les documents dans une langue nationale (français, allemand, italien) ou en anglais. <b>Un document en espagnol doit être accompagné d\'une traduction officielle.</b></p>
<h2>Qui traduit ?</h2><p>Un traducteur juré ou officiel reconnu. En Suisse romande, la traduction se fait en général en français. Demande à l\'office qui recevra ton dossier s\'il exige que la signature du traducteur soit légalisée.</p>
<h2>Comment économiser</h2><ul><li>L\'Espagne délivre des extraits plurilingues (modèle international) : les offices suisses n\'exigent pas la traduction des actes internationaux.</li><li>Fais traduire l\'apostille dans la même commande.</li><li>Demande d\'abord la liste exacte : ne traduis pas des documents que personne ne t\'a demandés.</li></ul>`],
  src:[['Ville de Lausanne · documents étrangers',OFF.laus]]},
 visa:{t:['Visa D: vivir en Suiza fuera de la UE','Visa D : vivre en Suisse hors UE'],d:['El orden de los pasos para colombianos, peruanos, mexicanos…','L\'ordre des étapes pour Colombiens, Péruviens, Mexicains…'],
  body:[`<p>Si no tienes pasaporte europeo, no puedes llegar como turista y «arreglar los papeles» después. Para estancias de más de 90 días necesitas una <b>visa nacional D</b>, y esa visa está sometida a la autorización de la autoridad de migración del cantón.</p>
<h2>El orden</h2><ol><li><b>El motivo primero</b>: contrato de trabajo, admisión en una escuela o un familiar en Suiza que te reagrupa.</li><li><b>La solicitud de permiso</b> la presenta el empleador, la escuela o tu familiar ante el cantón (en Vaud, el SPOP). En algunos casos la Confederación (SEM) también debe aprobarla.</li><li><b>La visa D</b> se pide en la representación suiza competente para tu país, con el formulario de visa D, pasaporte válido y los documentos del motivo.</li><li><b>Llegada</b>: te anuncias en tu comuna en los 14 días siguientes.</li></ol>
<div class="callout">Para trabajar, las personas de fuera de la UE solo obtienen permiso si son cualificadas y dentro de cupos anuales. Es el empleador quien hace la solicitud.</div>
<p>Si ya tienes un permiso de residencia válido de otro país Schengen o una visa D válida, no necesitas visa para entrar, pero sí el permiso suizo.</p>`,
`<p>Sans passeport européen, tu ne peux pas arriver comme touriste et « régulariser » ensuite. Pour un séjour de plus de 90 jours, il faut un <b>visa national D</b>, soumis à l\'autorisation de l\'autorité cantonale de migration.</p>
<h2>L\'ordre</h2><ol><li><b>Le motif d\'abord</b> : contrat de travail, admission dans une école ou un proche en Suisse qui fait un regroupement familial.</li><li><b>La demande de permis</b> est déposée par l\'employeur, l\'école ou ton proche auprès du canton (dans le canton de Vaud, le SPOP). Dans certains cas, la Confédération (SEM) doit aussi l\'approuver.</li><li><b>Le visa D</b> se demande auprès de la représentation suisse compétente pour ton pays, avec le formulaire de visa D, un passeport valable et les documents du motif.</li><li><b>Arrivée</b> : tu t\'annonces à ta commune dans les 14 jours.</li></ol>
<div class="callout">Pour travailler, les ressortissants hors UE n\'obtiennent un permis que s\'ils sont qualifiés et dans la limite de contingents annuels. C\'est l\'employeur qui fait la demande.</div>
<p>Si tu as déjà un titre de séjour valable d\'un autre pays Schengen ou un visa D valable, tu n\'as pas besoin de visa pour entrer, mais il te faut le permis suisse.</p>`],
  src:[['SEM · entrée avec visa',OFF.sem]]},
 comuna:{t:['Anunciarte en tu comuna','T\'annoncer à ta commune'],d:['El primer trámite al llegar: qué llevar y en qué plazo.','La première démarche à l\'arrivée : quoi apporter et dans quel délai.'],
  body:[`<p>En Suiza, todo empieza en la oficina de habitantes de tu comuna (en francés: <i>contrôle des habitants</i> u <i>office de la population</i>). Ahí declaras tu llegada y tu dirección, y se pone en marcha tu permiso.</p>
<h2>Plazo</h2><p>En los <b>14 días</b> siguientes a tu llegada, y antes de empezar a trabajar.</p>
<h2>Qué llevar normalmente</h2><ul><li>Pasaporte o documento de identidad válido (y visa D si eres de fuera de la UE).</li><li>Contrato de alquiler o carta de la persona que te aloja.</li><li>Contrato de trabajo, admisión escolar o documentos del motivo.</li><li>Fotos tipo pasaporte.</li><li>Documentos de estado civil (nacimiento, matrimonio) si vienes con familia.</li></ul>
<div class="callout ok">Cada comuna publica su propia lista. Revísala en su página web antes de ir para no tener que volver.</div>`,
`<p>En Suisse, tout commence au contrôle des habitants (ou office de la population) de ta commune. Tu y déclares ton arrivée et ton adresse, et ton permis est lancé.</p>
<h2>Délai</h2><p>Dans les <b>14 jours</b> suivant ton arrivée, et avant de commencer à travailler.</p>
<h2>À apporter en général</h2><ul><li>Passeport ou pièce d\'identité valable (et visa D si tu viens hors UE).</li><li>Bail ou attestation de la personne qui t\'héberge.</li><li>Contrat de travail, attestation d\'école ou documents du motif.</li><li>Photos format passeport.</li><li>Documents d\'état civil (naissance, mariage) si tu viens en famille.</li></ul>
<div class="callout ok">Chaque commune publie sa propre liste. Consulte son site avant d\'y aller pour ne pas devoir revenir.</div>`],
  src:[['VD · entrée et séjour UE',OFF.vdue]]},
 lamal:{t:['Seguro médico (LAMal) y subsidio','Assurance maladie (LAMal) et subside'],d:['Obligatorio para todos: plazo, cómo elegir y ayudas.','Obligatoire pour tous : délai, comment choisir et aides.'],
  body:[`<p>En Suiza el seguro médico básico es <b>obligatorio</b> y no lo paga el empleador: lo contratas tú con la aseguradora que elijas. La cobertura básica es la misma en todas; cambian el precio, la franquicia y el modelo.</p>
<h2>Plazo</h2><p>Tienes <b>3 meses</b> desde tu llegada para afiliarte. Si te afilias a tiempo, el seguro cubre desde el día de tu llegada.</p>
<h2>Cómo bajar la prima</h2><ul><li><b>Franquicia</b>: cuanto más alta, más barata la prima (pero pagas más si te enfermas).</li><li><b>Modelos</b> médico de familia, red de salud o telemedicina: suelen ser más baratos.</li><li><b>Subsidio cantonal</b>: según tus ingresos, el cantón puede pagar parte de tu prima. Cada cantón tiene sus reglas y su formulario.</li></ul>
<div class="callout">Si no te afilias en el plazo, la autoridad te asigna una aseguradora de oficio y puede cobrarte un recargo.</div>`,
`<p>En Suisse, l\'assurance maladie de base est <b>obligatoire</b> et ce n\'est pas l\'employeur qui la paie : tu la souscris toi-même auprès de l\'assureur de ton choix. La couverture de base est la même partout ; ce qui change, c\'est le prix, la franchise et le modèle.</p>
<h2>Délai</h2><p>Tu as <b>3 mois</b> depuis ton arrivée pour t\'affilier. Si tu t\'affilies à temps, l\'assurance te couvre dès le jour de ton arrivée.</p>
<h2>Comment réduire la prime</h2><ul><li><b>Franchise</b> : plus elle est haute, moins la prime coûte (mais tu paies plus si tu es malade).</li><li><b>Modèles</b> médecin de famille, réseau de soins ou télémédecine : souvent moins chers.</li><li><b>Subside cantonal</b> : selon tes revenus, le canton peut payer une partie de ta prime. Chaque canton a ses règles et son formulaire.</li></ul>
<div class="callout">Si tu ne t\'affilies pas dans le délai, l\'autorité t\'attribue un assureur d\'office et peut appliquer un supplément.</div>`],src:[]},
 permisos:{t:['Los permisos suizos: L, B, C, F, G','Les permis suisses : L, B, C, F, G'],d:['Qué significa cada letra y qué derechos da.','Ce que veut dire chaque lettre et quels droits elle donne.'],
  body:[`<div class="facts"><div class="fact"><small>L</small><b>Corta duración</b>Menos de un año, ligado a un contrato.</div><div class="fact"><small>B</small><b>Residencia</b>Permiso anual renovable. El más común al llegar.</div><div class="fact"><small>C</small><b>Establecimiento</b>Residencia de larga duración, tras años en Suiza.</div><div class="fact"><small>F</small><b>Admisión provisional</b>Personas cuyo regreso no es posible por ahora.</div><div class="fact"><small>G</small><b>Fronterizo</b>Vives fuera de Suiza y trabajas aquí.</div></div>
<h2>UE y fuera de la UE</h2><p>Con pasaporte europeo, un contrato de un año o más da en general un permiso B; un contrato más corto, un L. Fuera de la UE, el B suele ser de un año renovable bajo condiciones, y el C se obtiene después de 5 o 10 años de residencia según el caso.</p>
<h2>Del B al C</h2><p>Además de los años de residencia, cuentan la integración y el nivel de idioma (francés en Suiza romanda). Prepara un certificado de idioma reconocido con tiempo.</p>`,
`<div class="facts"><div class="fact"><small>L</small><b>Courte durée</b>Moins d\'un an, lié à un contrat.</div><div class="fact"><small>B</small><b>Séjour</b>Permis annuel renouvelable. Le plus courant à l\'arrivée.</div><div class="fact"><small>C</small><b>Établissement</b>Séjour durable, après des années en Suisse.</div><div class="fact"><small>F</small><b>Admission provisoire</b>Personnes dont le renvoi n\'est pas possible pour l\'instant.</div><div class="fact"><small>G</small><b>Frontalier</b>Tu vis hors de Suisse et tu travailles ici.</div></div>
<h2>UE et hors UE</h2><p>Avec un passeport européen, un contrat d\'un an ou plus donne en général un permis B ; un contrat plus court, un L. Hors UE, le B est en général annuel et renouvelable sous conditions, et le C s\'obtient après 5 ou 10 ans de séjour selon les cas.</p>
<h2>Du B au C</h2><p>En plus des années de séjour, l\'intégration et le niveau de langue comptent (français en Suisse romande). Prépare un certificat de langue reconnu à l\'avance.</p>`],src:[]},
 familia:{t:['Reagrupación familiar','Regroupement familial'],d:['Traer a tu pareja o a tus hijos: condiciones y documentos.','Faire venir ton conjoint ou tes enfants : conditions et documents.'],
  body:[`<p>Si vives en Suiza con un permiso B, C o L, puedes pedir que tu familia (pareja casada o registrada, hijos menores) venga a vivir contigo.</p>
<h2>Condiciones habituales (ejemplo de Vaud)</h2><ul><li>Vivir juntos en el mismo hogar.</li><li>Tener una vivienda adecuada para toda la familia.</li><li>No depender de la ayuda social.</li><li>No recibir prestaciones complementarias AVS/AI, ni poder obtenerlas por la reagrupación.</li></ul>
<h2>Documentos frecuentes</h2><ul><li>Acta de matrimonio o de unión, apostillada y traducida.</li><li>Actas de nacimiento de los hijos con filiación.</li><li>Si un solo padre trae a un hijo: documento oficial de custodia o autoridad parental, legalizado y traducido.</li><li>Contrato de alquiler, salarios y contrato de trabajo de la persona que vive en Suiza.</li></ul>
<div class="callout">Hay plazos para pedir la reagrupación. Si se pasan, el caso se complica: consulta a nuestro equipo cuanto antes.</div>`,
`<p>Si tu vis en Suisse avec un permis B, C ou L, tu peux demander que ta famille (conjoint marié ou partenaire enregistré, enfants mineurs) vienne vivre avec toi.</p>
<h2>Conditions habituelles (exemple vaudois)</h2><ul><li>Vivre en ménage commun.</li><li>Disposer d\'un logement approprié pour toute la famille.</li><li>Ne pas dépendre de l\'aide sociale.</li><li>Ne pas percevoir de prestations complémentaires AVS/AI, ni pouvoir en obtenir grâce au regroupement.</li></ul>
<h2>Documents fréquents</h2><ul><li>Acte de mariage ou de partenariat, apostillé et traduit.</li><li>Actes de naissance des enfants avec filiation.</li><li>Si un seul parent fait venir un enfant : document officiel de garde ou d\'autorité parentale, légalisé et traduit.</li><li>Bail, salaires et contrat de travail de la personne qui vit en Suisse.</li></ul>
<div class="callout">Il existe des délais pour demander le regroupement. S\'ils sont dépassés, le dossier se complique : contacte notre équipe au plus vite.</div>`],src:[]},
 impuestos:{t:['Impuesto en la fuente','Impôt à la source'],d:['Por qué te descuentan impuestos del salario y cómo recuperar.','Pourquoi on te retient des impôts sur le salaire et comment récupérer.'],
  body:[`<p>Si eres extranjero sin permiso C, tu empleador descuenta normalmente los impuestos directamente de tu salario cada mes: es el <b>impuesto en la fuente</b>. La tasa depende del cantón, de tu salario, de tu estado civil y de tus hijos.</p>
<h2>¿Puedo pagar menos?</h2><p>Puedes pedir una <b>tasación ordinaria ulterior</b> para declarar tus gastos (3er pilar, transporte, cuidado de hijos…). Por encima de cierto salario anual es obligatoria. La solicitud tiene un plazo: normalmente hasta el 31 de marzo del año siguiente.</p>
<div class="callout">Una vez que pides la tasación ordinaria, ya no hay vuelta atrás para los años siguientes. Evalúa bien antes de hacerlo.</div>`,
`<p>Si tu es étranger sans permis C, ton employeur retient en général les impôts directement sur ton salaire chaque mois : c\'est l\'<b>impôt à la source</b>. Le taux dépend du canton, de ton salaire, de ton état civil et de tes enfants.</p>
<h2>Puis-je payer moins ?</h2><p>Tu peux demander une <b>taxation ordinaire ultérieure</b> pour déclarer tes frais (3e pilier, transports, garde d\'enfants…). Au-delà d\'un certain salaire annuel, elle est obligatoire. La demande a un délai : en général jusqu\'au 31 mars de l\'année suivante.</p>
<div class="callout">Une fois la taxation ordinaire demandée, on ne peut plus revenir en arrière les années suivantes. Réfléchis bien avant.</div>`],src:[]}
};
