const SUB={
 VD:{org:'OVAM · Office vaudois de l\'assurance-maladie',auto:false,
  how:['No es automático: lo pides en línea en vd.ch o en la agencia de seguros sociales (AAS) de tu región. Puedes estimar tu derecho en línea con tu última decisión de impuestos. La OVAM te responde por carta.','Pas automatique : tu le demandes en ligne sur vd.ch ou à l\'agence d\'assurances sociales (AAS) de ta région. Tu peux estimer ton droit en ligne avec ta dernière décision de taxation. L\'OVAM te répond par courrier.'],
  when:['En cualquier momento del año.','À tout moment de l\'année.'],src:'https://www.vd.ch/sante-soins-et-handicap/assurance-maladie/subside-a-lassurance-maladie'},
 GE:{org:'SAM · Service de l\'assurance-maladie',auto:true,
  how:['En principio automático, según tus ingresos de hace dos años. Pero algunas personas deben pedirlo: las que se instalaron en Ginebra en 2025 o 2026, las que pagan impuesto en la fuente y los jóvenes adultos de 19 a 25 años.','En principe automatique, sur la base de ton revenu d\'il y a deux ans. Mais certaines personnes doivent le demander : celles qui se sont domiciliées à Genève en 2025 ou 2026, les personnes imposées à la source et les jeunes adultes de 19 à 25 ans.'],
  when:['Recién llegados 2025–2026: expediente completo antes del 31 de diciembre de 2026.','Nouveaux arrivants 2025–2026 : dossier complet avant le 31 décembre 2026.'],src:'https://www.ge.ch/demander-subside-assurance-maladie-2026/domiciliation-geneve-2025-2026'},
 VS:{org:'Caisse de compensation du canton du Valais',auto:true,
  how:['En general automático, según los datos fiscales. Si tu situación familiar o financiera cambió (matrimonio, nacimiento, divorcio, fin del paro…), debes hacer una solicitud especial.','En général automatique, sur la base des données fiscales. Si ta situation familiale ou financière a changé (mariage, naissance, divorce, fin du chômage…), tu dois faire une demande spéciale.'],
  when:['Tras un cambio de situación.','Après un changement de situation.'],src:'https://www.vs.ch/web/communication/w/r%C3%A9duction-individuelle-des-primes-d-assurance-maladie-2026'},
 FR:{org:'Caisse de compensation · ECAS Fribourg',auto:false,
  how:['La caja envía el formulario a las personas que podrían tener derecho. Si no lo recibes, lo puedes pedir; también si llegaste del extranjero durante el año. El derecho empieza el mes en que presentas la solicitud.','La caisse envoie le formulaire aux ayants droit potentiels. Si tu ne le reçois pas, tu peux le demander, aussi si tu es arrivé de l\'étranger en cours d\'année. Le droit commence le mois où tu déposes la demande.'],
  when:['A más tardar el 31 de agosto de 2026.','Au plus tard le 31 août 2026.'],src:'https://www.ecasfr.ch'},
 NE:{org:'OCAB · Office cantonal de l\'assurance-maladie et des bourses',auto:true,
  how:['Evaluación automática a partir de tu declaración de impuestos. Si no recibes nada (por ejemplo, impuesto en la fuente o recién llegado), pregunta a la OCAB o a tu guichet social régional.','Évaluation automatique à partir de ta déclaration d\'impôt. Si tu ne reçois rien (par exemple imposé à la source ou nouvel arrivant), renseigne-toi auprès de l\'OCAB ou de ton guichet social régional.'],
  when:['Si no recibiste la carta.','Si tu n\'as pas reçu de courrier.'],src:'https://www.ne.ch'},
 JU:{org:'Caisse de compensation du canton du Jura',auto:true,
  how:['La caja informa por carta a los posibles beneficiarios. Si crees que tienes derecho y no recibiste nada, contáctala.','La caisse informe par courrier les bénéficiaires potentiels. Si tu penses y avoir droit et que tu n\'as rien reçu, contacte-la.'],
  when:['Si no recibiste la carta.','Si tu n\'as pas reçu de courrier.'],src:'https://www.jura.ch'}
};
function daysTo30Nov(){const now=new Date();let y=now.getFullYear();let d=new Date(y,10,30,23,59);if(now>d)d=new Date(y+1,10,30,23,59);return Math.ceil((d-now)/864e5);}
Object.assign(G,{
 subsidio:{t:['Subsidio del seguro médico, cantón por cantón','Subside d\'assurance maladie, canton par canton'],d:['Quién lo da, si es automático y cómo pedirlo en Suiza romanda.','Qui le verse, s\'il est automatique et comment le demander en Suisse romande.'],
  body:()=>[`<p>El subsidio reduce tu prima de seguro básico. No te dan el dinero a ti: el cantón lo paga directamente a tu aseguradora, que lo descuenta de tu factura. Solo cubre el seguro básico (LAMal), no los complementarios.</p>${subTable()}<div class="callout"><b>Truco:</b> si pagas impuesto en la fuente o llegaste hace poco, el cantón a menudo no tiene tus datos fiscales. En ese caso casi siempre tienes que pedirlo tú.</div>`,
  `<p>Le subside réduit ta prime d'assurance de base. L'argent ne t'est pas versé : le canton le paie directement à ton assureur, qui le déduit de ta facture. Il couvre seulement l'assurance de base (LAMal), pas les complémentaires.</p>${subTable()}<div class="callout"><b>Astuce :</b> si tu es imposé à la source ou arrivé récemment, le canton n'a souvent pas tes données fiscales. Dans ce cas, c'est presque toujours à toi de le demander.</div>`],
  src:[['vd.ch · subside','https://www.vd.ch/sante-soins-et-handicap/assurance-maladie/subside-a-lassurance-maladie'],['ge.ch · subside 2026','https://www.ge.ch/demander-subside-assurance-maladie-2026/domiciliation-geneve-2025-2026'],['vs.ch · RIP 2026','https://www.vs.ch/web/communication/w/r%C3%A9duction-individuelle-des-primes-d-assurance-maladie-2026']]},
 cambiar:{t:['Cambiar de seguro antes del 30 de noviembre','Changer de caisse avant le 30 novembre'],d:['El truco más rentable del año: misma cobertura, prima más baja.','L\'astuce la plus rentable de l\'année : même couverture, prime plus basse.'],
  body:[`<p>El seguro básico cubre exactamente lo mismo en todas las aseguradoras. Si otra es más barata, cambiar no te hace perder nada, incluso si estás enfermo.</p>
<h2>Las fechas</h2><ul><li><b>30 de noviembre</b>: tu carta de rescisión debe <b>llegar</b> a tu aseguradora actual (no basta con enviarla). Envíala por carta certificada antes del <b>15 de noviembre</b>.</li><li><b>30 de noviembre</b>: también es el plazo para cambiar de modelo (médico de familia, telemedicina…) o bajar tu franquicia.</li><li><b>31 de diciembre</b>: plazo para subir tu franquicia.</li><li>Inscríbete en la nueva aseguradora antes del 31 de diciembre.</li></ul>
<div class="callout">Si tienes primas impagadas con recordatorio, la aseguradora puede bloquear tu cambio. Paga primero o pide un plan de pagos.</div>
<p>Los complementarios tienen otros plazos (a menudo el 30 de septiembre). Mira tu contrato.</p>`,
`<p>L'assurance de base couvre exactement la même chose chez tous les assureurs. Si un autre est moins cher, changer ne te fait rien perdre, même si tu es malade.</p>
<h2>Les dates</h2><ul><li><b>30 novembre</b> : ta lettre de résiliation doit <b>arriver</b> chez ton assureur actuel (l'envoyer ne suffit pas). Envoie-la en recommandé avant le <b>15 novembre</b>.</li><li><b>30 novembre</b> : c'est aussi le délai pour changer de modèle (médecin de famille, télémédecine…) ou baisser ta franchise.</li><li><b>31 décembre</b> : délai pour augmenter ta franchise.</li><li>Inscris-toi chez le nouvel assureur avant le 31 décembre.</li></ul>
<div class="callout">Si tu as des primes impayées ayant fait l'objet d'un rappel, l'assureur peut bloquer ton changement. Paie d'abord ou demande un plan de paiement.</div>
<p>Les complémentaires ont d'autres délais (souvent le 30 septembre). Vérifie ton contrat.</p>`],
  src:[['OFSP · changement d\'assureur 2026','https://www.bag.admin.ch/dam/fr/sd-web/92VbSMPCd--v/PG27-FB-Versichererwechsel_FR.pdf']]},
 ayudasocial:{t:['RI y ayuda social: lo que debes saber sobre tu permiso','RI et aide sociale : ce qu\'il faut savoir pour ton permis'],d:['Cómo funciona el RI en Vaud y por qué puede afectar a tu permiso.','Comment fonctionne le RI vaudois et pourquoi il peut toucher ton permis.'],
  body:[`<p>El <b>revenu d'insertion (RI)</b> es la ayuda social del cantón de Vaud. Garantiza el mínimo vital a personas mayores de edad domiciliadas en Vaud (suizas o extranjeras con permiso) cuyos ingresos no alcanzan. Incluye una ayuda financiera, acompañamiento social y medidas de inserción profesional. En los otros cantones existe una ayuda social equivalente (en Ginebra, el Hospice général).</p>
<h2>Cómo pedirlo (Vaud)</h2><p>Contactas el <b>Centro social regional (CSR)</b> de tu comuna. Lleva tus 3 últimos extractos de todas tus cuentas (en Suiza y en el extranjero), tu contrato de alquiler y el último pago del alquiler.</p>
<h2>Atención: el impacto en tu permiso</h2><ul><li><b>Permiso B</b>: la ley permite revocarlo o no renovarlo si tú o una persona a tu cargo dependéis de la ayuda social. Se necesita un riesgo concreto de dependencia, no basta una simple dificultad financiera.</li><li><b>Permiso C</b>: solo si la dependencia es duradera y en gran medida.</li><li>La ayuda social también puede bloquear una reagrupación familiar.</li><li>Las prestaciones complementarias AVS/AI no son un motivo de revocación del permiso C, según el Tribunal federal.</li></ul>
<div class="callout ok"><b>Antes de pedir el RI</b>, revisa las ayudas que no son ayuda social: subsidio LAMal, asignaciones familiares, PC Familias (Vaud), paro. Y si necesitas ayuda para vivir, pídela: tu situación se evalúa caso por caso. Nuestro equipo te ayuda a elegir la vía correcta.</div>`,
`<p>Le <b>revenu d'insertion (RI)</b> est l'aide sociale du canton de Vaud. Il garantit le minimum vital aux personnes majeures domiciliées dans le canton (suisses ou étrangères avec permis) dont les revenus ne suffisent pas. Il comprend une aide financière, un appui social et des mesures d'insertion professionnelle. Les autres cantons ont une aide sociale équivalente (à Genève, l'Hospice général).</p>
<h2>Comment le demander (Vaud)</h2><p>Tu contactes le <b>Centre social régional (CSR)</b> de ta commune. Apporte les 3 derniers relevés de tous tes comptes (en Suisse et à l'étranger), ton bail et la preuve du dernier loyer payé.</p>
<h2>Attention : l'impact sur ton permis</h2><ul><li><b>Permis B</b> : la loi permet de le révoquer ou de ne pas le renouveler si toi ou une personne à ta charge dépendez de l'aide sociale. Il faut un risque concret de dépendance, de simples soucis financiers ne suffisent pas.</li><li><b>Permis C</b> : seulement en cas de dépendance durable et dans une large mesure.</li><li>L'aide sociale peut aussi bloquer un regroupement familial.</li><li>Les prestations complémentaires AVS/AI ne sont pas un motif de révocation du permis C, selon le Tribunal fédéral.</li></ul>
<div class="callout ok"><b>Avant de demander le RI</b>, vérifie les aides qui ne sont pas de l'aide sociale : subside LAMal, allocations familiales, PC Familles (Vaud), chômage. Et si tu as besoin d'aide pour vivre, demande-la : ta situation est examinée au cas par cas. Notre équipe t'aide à choisir la bonne voie.</div>`],
  src:[['vd.ch · revenu d\'insertion','https://www.vd.ch/aides-financieres-et-soutien-social/aides-financieres-et-comment-les-demander/revenu-dinsertion-ri'],['vd.ch · demander le RI','https://www.vd.ch/prestation-detail/prestation/demander-le-revenu-dinsertion/']]},
 pcfamilias:{t:['PC Familias (Vaud)','PC Familles (Vaud)'],d:['Un complemento para familias que trabajan y no llegan a fin de mes.','Un complément pour les familles qui travaillent et n\'arrivent pas à boucler le mois.'],
  body:[`<p>Las <b>prestaciones complementarias para familias</b> ayudan a las familias con hijos menores de 16 años que <b>trabajan</b> pero no cubren sus necesidades esenciales. No son el RI.</p>
<h2>Condiciones principales</h2><ul><li>Vivir en el cantón de Vaud desde hace al menos 3 años, con un permiso válido.</li><li>Vivir con hijos menores de 16 años.</li><li>Ingresos insuficientes frente a los gastos de la familia, según la ley.</li></ul>
<h2>Qué incluye</h2><ul><li>Una prestación mensual.</li><li>El reembolso de gastos de guardería y de enfermedad justificados (también, en algunos casos, para familias un poco por encima del límite).</li></ul>
<h2>Cómo pedirlas</h2><p>Estima tu derecho con el simulador en línea de vd.ch y presenta la solicitud en el centro regional de decisión (CRD) PC Familias. Se conceden por 12 meses renovables.</p>
<div class="callout">Ginebra tiene un sistema parecido (prestaciones complementarias familiares). Pregúntanos por tu cantón.</div>`,
`<p>Les <b>prestations complémentaires pour familles</b> aident les familles avec enfants de moins de 16 ans qui <b>travaillent</b> mais ne couvrent pas leurs besoins essentiels. Ce n'est pas le RI.</p>
<h2>Conditions principales</h2><ul><li>Être domicilié dans le canton de Vaud depuis au moins 3 ans, avec un titre de séjour valable.</li><li>Vivre avec des enfants de moins de 16 ans.</li><li>Revenus insuffisants par rapport aux dépenses de la famille, selon la loi.</li></ul>
<h2>Ce que ça comprend</h2><ul><li>Une prestation mensuelle.</li><li>Le remboursement des frais de garde et de maladie prouvés (dans certains cas aussi pour les familles légèrement au-dessus de la limite).</li></ul>
<h2>Comment les demander</h2><p>Estime ton droit avec le simulateur en ligne de vd.ch et dépose la demande au centre régional de décision (CRD) PC Familles. Elles sont accordées pour 12 mois renouvelables.</p>
<div class="callout">Genève a un système proche (prestations complémentaires familiales). Demande-nous pour ton canton.</div>`],
  src:[['vd.ch · PC Familles','https://www.vd.ch/aides-financieres-et-soutien-social/aides-financieres-et-comment-les-demander/pc-familles']]},
 asignaciones:{t:['Asignaciones familiares','Allocations familiales'],d:['Dinero cada mes por cada hijo: montos 2026 y cómo cobrarlas.','De l\'argent chaque mois pour chaque enfant : montants 2026 et comment les toucher.'],
  body:[`<p>Si trabajas en Suiza y tienes hijos, recibes una asignación mensual por cada hijo, normalmente a través de tu salario. El cantón fija el monto, por encima de un mínimo federal.</p>
<div class="facts"><div class="fact"><small>Vaud 2026 · hijo &lt; 16</small><b>CHF 322 / mes</b>CHF 365 desde el 3er hijo</div><div class="fact"><small>Vaud 2026 · en formación</small><b>CHF 425 / mes</b>Hasta los 25 años · CHF 468 desde el 3er</div><div class="fact"><small>Vaud 2026 · nacimiento</small><b>CHF 1'617</b>Pago único</div><div class="fact"><small>Neuchâtel 2026 · hijo</small><b>CHF 240 / mes</b>CHF 270 desde el 3er · nacimiento CHF 1'200</div></div>
<h2>Trucos</h2><ul><li>Tus hijos <b>no tienen que vivir en Suiza</b> en todos los casos: depende de los acuerdos con el país. Pregúntanos.</li><li>Si no trabajas, también puedes tener derecho como persona sin actividad lucrativa.</li><li>Avisa a tu empleador cada nacimiento: la asignación de nacimiento no siempre es automática.</li></ul>`,
`<p>Si tu travailles en Suisse et as des enfants, tu reçois une allocation mensuelle par enfant, en général avec ton salaire. Le canton fixe le montant, au-dessus d'un minimum fédéral.</p>
<div class="facts"><div class="fact"><small>Vaud 2026 · enfant &lt; 16</small><b>CHF 322 / mois</b>CHF 365 dès le 3e enfant</div><div class="fact"><small>Vaud 2026 · en formation</small><b>CHF 425 / mois</b>Jusqu'à 25 ans · CHF 468 dès le 3e</div><div class="fact"><small>Vaud 2026 · naissance</small><b>CHF 1'617</b>Versement unique</div><div class="fact"><small>Neuchâtel 2026 · enfant</small><b>CHF 240 / mois</b>CHF 270 dès le 3e · naissance CHF 1'200</div></div>
<h2>Astuces</h2><ul><li>Tes enfants <b>ne doivent pas forcément vivre en Suisse</b> : ça dépend des accords avec le pays. Demande-nous.</li><li>Si tu ne travailles pas, tu peux aussi y avoir droit comme personne sans activité lucrative.</li><li>Annonce chaque naissance à ton employeur : l'allocation de naissance n'est pas toujours automatique.</li></ul>`],
  src:[['Caisse AVS Vaud · prestations familiales 2026','https://www.caisseavsvaud.ch'],['RSN Neuchâtel 822.101.1','https://rsn.ne.ch/DATA/program/books/rsne/pdf/822.101.1.pdf']]}
});
function subTable(){
  return `<div class="tbl"><table><thead><tr><th>${T(['Cantón','Canton'])}</th><th>${T(['Organismo','Organisme'])}</th><th>${T(['¿Automático?','Automatique ?'])}</th><th>${T(['Cómo','Comment'])}</th><th>${T(['Plazo','Délai'])}</th></tr></thead><tbody>${CANTONS.map(c=>{const s=SUB[c.k];return `<tr><td><b>${T(c.n)}</b></td><td>${s.org}</td><td>${s.auto?`<span class="tag ok">${T(['En general sí','En général oui'])}</span>`:`<span class="tag warn">${T(['No, pedirlo','Non, à demander'])}</span>`}</td><td>${T(s.how)}</td><td>${T(s.when)}</td></tr>`}).join('')}</tbody></table></div>`;
}
