  body:()=>`${T(G.cambiar.body)}<h2>${T(G.lamal.body).split('<h2>')[2]}
   <h2>${T(['Paso a paso','Pas à pas'])}</h2><ol class="steplist"><li>${T(['Compara las primas de tu región en el calculador oficial de la Confederación (Priminfo).','Compare les primes de ta région sur le calculateur officiel de la Confédération (Priminfo).'])}</li><li>${T(['Envía la rescisión por carta certificada antes del 15 de noviembre.','Envoie la résiliation en recommandé avant le 15 novembre.'])}</li><li>${T(['Inscríbete en la nueva aseguradora antes del 31 de diciembre.','Inscris-toi chez le nouvel assureur avant le 31 décembre.'])}</li><li>${T(['Si tienes subsidio, avisa al cantón del cambio si te lo pide.','Si tu as un subside, annonce le changement au canton s\'il le demande.'])}</li></ol>`,
