      <div class="tp-nav">${(()=>{const i=TABS.indexOf(tab);const p=TABS[i-1],n=TABS[i+1];return `${p?`<a class="btn ghost sm" href="${tabLink(p.k)}">← ${T(p.t)}</a>`:'<span></span>'}${n?`<a class="btn ghost sm" href="${tabLink(n.k)}">${T(n.t)} →</a>`:''}`})()}</div>
