const slugId=t=>plain(t).trim().toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'').slice(0,48);
function midCta(){return `<aside class="midcta"><div><b>${T(['¿Tu caso es diferente?','Ta situation est particulière ?'])}</b><p>${T(['Una persona que trabaja en la administración suiza revisa tu caso contigo y te dice qué hacer, en español. 30 minutos por videollamada.','Une personne qui travaille dans l\'administration suisse regarde ton cas avec toi et te dit quoi faire, en espagnol ou en français. 30 minutes en visio.'])}</p></div><div class="midcta-act"><a class="btn" href="#precios">${T(['Hablar con una persona · CHF 39','Parler à une personne · CHF 39'])}</a><a href="#club">${T(['O únete al Club · CHF 9.99/mes','Ou rejoins le Club · CHF 9.99/mois'])} →</a></div></aside>`;}
function enrichPost(html){
  const used=new Set();
  html=html.replace(/<h2(\s[^>]*)?>([\s\S]*?)<\/h2>/g,(m,a,txt)=>{if(a&&/\bid=/.test(a)){used.add((a.match(/id="([^"]+)"/)||[])[1]);return m;}let id=slugId(txt)||'sec';while(used.has(id))id+='-2';used.add(id);return `<h2 id="${id}"${a||''}>${txt}</h2>`;});
  const heads=[...html.matchAll(/<h2 id="([^"]+)"[^>]*>([\s\S]*?)<\/h2>/g)];
  if(!/class="toc"/.test(html)&&heads.length>=3){const toc=`<nav class="toc" aria-label="${T(['Índice','Sommaire'])}"><b>${T(['En este artículo','Dans cet article'])}</b><ol>${heads.map(h=>`<li><a href="#${h[1]}">${plain(h[2]).trim()}</a></li>`).join('')}</ol></nav>`;html=html.replace(/<h2 id=/,toc+'<h2 id=');}
  if(heads.length>=4){const at=heads[Math.floor(heads.length/2)][0];const i=html.indexOf(at);if(i>0)html=html.slice(0,i)+midCta()+html.slice(i);}
  return html;}
function authorBox(p){return `<aside class="authorbox"><span class="ab-ico" aria-hidden="true">RS</span><div><b>${T(['Escrito y revisado por el equipo Ruta Suiza','Écrit et vérifié par l\'équipe Ruta Suiza'])}</b><p>${T(['Somos bilingües (español y francés) y trabajamos en la administración suiza, en la Suiza romanda. Verificamos cada dato en fuentes oficiales. Última revisión: ','Nous sommes bilingues (espagnol et français) et travaillons dans l\'administration suisse, en Suisse romande. Chaque information est vérifiée dans des sources officielles. Dernière vérification : '])}${fmtD(p.date)}. <a href="#nosotros">${T(['Quiénes somos','Qui sommes-nous'])} →</a></p><small>${T(['Información general, no asesoramiento jurídico. Las reglas pueden variar según el cantón y tu situación.','Information générale, pas un conseil juridique. Les règles peuvent varier selon le canton et ta situation.'])}</small></div></aside>`;}
function srcBox(p){return p.src&&p.src.length?`<section class="srcbox"><h2>${T(['Fuentes oficiales consultadas','Sources officielles consultées'])}</h2><ul>${p.src.map(x=>`<li><a href="${x[1]}" target="_blank" rel="noopener">${T(x[0])}</a></li>`).join('')}</ul></section>`:'';}
function vPost(slug){
  const p=POSTS.find(x=>x.slug===slug)||POSTS[0], L='/'+LANG, path=`${L}/blog/${p.slug}`;
  const more=POSTS.filter(x=>x!==p);
  return `<article class="article post"><div class="crumbs"><a href="#inicio">Ruta Suiza</a> › <a href="#blog">Blog</a> › ${T(p.cat)}</div>
   <span class="nkick">${T(p.cat)}</span><h1>${T(p.t)}</h1>
   <div class="na-meta"><span>${T(['Actualizado el ','Mis à jour le '])}${fmtD(p.date)}</span><span>⏱ ${Math.max(2,Math.round(T(p.body).replace(/<[^>]+>/g,' ').split(/\s+/).length/200))} min ${T(['de lectura','de lecture'])}</span><span>${T(['Por el equipo Ruta Suiza','Par l\'équipe Ruta Suiza'])}</span></div>
   ${NEWS_IMG[p.img]?`<figure class="na-fig">${pic(p.img,"(max-width:760px) 100vw, 720px","",true,T(p.t))}<figcaption>${T(['Foto','Photo'])}: <a href="${NEWS_IMG[p.img].url}" target="_blank" rel="noopener">${NEWS_IMG[p.img].by}</a> · ${NEWS_IMG[p.img].lic} · ${T(['imagen ilustrativa','image d\'illustration'])}</figcaption></figure>`:''}
   ${enrichPost(T(p.body))}${p.faq?faqBlock(p.faq):''}${srcBox(p)}${authorBox(p)}${toolsStrip()}
   <a class="na-share" href="https://wa.me/?text=${encodeURIComponent(altTxt(T(p.t))+' · '+SITE+'/'+LANG+'/blog/'+p.slug)}" target="_blank" rel="noopener">${T(['Compartir por WhatsApp','Partager sur WhatsApp'])}</a>
   <div class="callout"><b>${T(['Guía completa','Guide complet'])}:</b> <a href="#vivir-en-suiza">${T(PILLAR.t)}</a></div>
   ${helpBanner()}${more.length?`<section class="sec"><h2>${T(['Más artículos','Plus d\'articles'])}</h2><div class="bgrid">${more.map(postCard).join('')}</div></section>`:''}</article>
   ${ld(articleLd(T(p.t),T(p.d),p.date,path,NEWS_IMG[p.img]?`/news/${p.img}.jpg`:null))}${p.faq?ld(faqLd(p.faq)):''}${ld(crumbsLd([['Ruta Suiza',L],['Blog',L+'/blog'],[T(p.t),path]]))}`;
}

