/** Home: Club right after the hero. */
function clubPromo(){
  return `<section class="club-promo"><div><span class="ccb-k">Club Ruta Suiza</span><h2>${T(['Una persona que trabaja en la administración suiza, a tu lado por','Une personne qui travaille dans l\'administration suisse, à tes côtés pour'])} <em>${CLUB_PRICE} ${T(UI.month)}</em></h2>
  <ul class="cp-list">${CLUB_BEN.slice(0,4).map(b=>`<li><span aria-hidden="true">${b[0]}</span><b>${T(b[1])}</b></li>`).join('')}</ul></div>
  <div class="cp-act"><button class="btn buy-club">${T(['Unirme al Club','Rejoindre le Club'])}</button><a href="#club" class="ccb-more">${T(['Ver el Club','Voir le Club'])} →</a><small class="paynote">${T(['Sin permanencia · pago con tarjeta','Sans engagement · paiement par carte'])}</small></div></section>`;
}
function vClub(){
  const pv='#privacidad';
  const faq=[
    [['¿Quién responde a mis preguntas?','Qui répond à mes questions ?'],['Siempre una persona de nuestro equipo que trabaja en la administración suiza. El grupo sirve para compartir experiencias, pero las explicaciones y respuestas vienen del equipo, nunca de otros miembros ni de un robot.','Toujours une personne de notre équipe qui travaille dans l\'administration suisse. Le groupe sert à partager des expériences, mais les explications et réponses viennent de l\'équipe, jamais d\'autres membres ni d\'un robot.']],
    [['¿Cómo funciona después de pagar?','Comment ça se passe après le paiement ?'],['Recibes al instante el acceso a tu grupo privado y las instrucciones para mandarnos tu primera carta. La suscripción se renueva cada mes.','Tu reçois tout de suite l\'accès à ton groupe privé et les instructions pour nous envoyer ta première lettre. L\'abonnement se renouvelle chaque mois.']],
    [['¿Puedo cancelar?','Je peux résilier ?'],['Sí, cuando quieras y sin permanencia: sigues teniendo acceso hasta el final del mes pagado.','Oui, quand tu veux et sans engagement : tu gardes l\'accès jusqu\'à la fin du mois payé.']],
    [['¿Qué pasa con mis cartas y mis datos?','Que deviennent mes lettres et mes données ?'],['Las tratamos de forma confidencial, solo para responderte, y las borramos después. Nunca se venden ni se comparten.','Nous les traitons de façon confidentielle, uniquement pour te répondre, puis nous les supprimons. Elles ne sont jamais vendues ni partagées.']],
    [['¿Cuánto cuesta?','Combien ça coûte ?'],['CHF 9.99 al mes, todo incluido. Las guías y Suiza News siguen siendo gratis para todos.','CHF 9.99 par mois, tout compris. Les guides et Suiza News restent gratuits pour tous.']]];
  return `<section class="club-hero"><div class="eyebrow">Club Ruta Suiza</div>
   <h1>${T(['Vive Suiza <em>sin estrés administrativo</em>.','Vis la Suisse <em>sans stress administratif</em>.'])}</h1>
   <p class="lead">${T(['Por CHF 9.99 al mes, una persona de nuestro equipo, que trabaja en la administración suiza, te explica tus cartas y responde a tus preguntas en español. Además: un grupo privado y eventos para conectar con otros miembros.','Pour CHF 9.99 par mois, une personne de notre équipe, qui travaille dans l\'administration suisse, t\'explique tes courriers et répond à tes questions en espagnol. En plus : un groupe privé et des événements pour te connecter avec d\'autres membres.'])}</p>
   <div class="club-cta">${clubBtn()}</div></section>
   <div class="club-grid">${CLUB_BEN.map(b=>`<div class="club-b"><span class="club-i" aria-hidden="true">${b[0]}</span><h3>${T(b[1])}</h3><p>${T(b[2])}</p></div>`).join('')}</div>
   <section class="club-offer"><div><span class="tag red">${T(['Todo incluido','Tout inclus'])}</span><h2>${T(['Club Ruta Suiza','Club Ruta Suiza'])}</h2><div class="price">${CLUB_PRICE} <small>${T(UI.month)}</small></div><p class="muted">${T(['Menos que un café a la semana para no volver a perder un plazo ni un derecho.','Moins qu\'un café par semaine pour ne plus jamais rater un délai ni un droit.'])}</p></div><div class="club-offer-b">${clubBtn()}</div></section>
   <section class="club-join" id="club-form"><div><h2>${T(['¿Todavía lo piensas?','Tu hésites encore ?'])}</h2><p class="muted">${T(['Déjanos tu correo y te enviamos más información, sin compromiso.','Laisse ton e-mail et on t\'envoie plus d\'informations, sans engagement.'])}</p></div>
    <form class="lform panel club-mini" id="clubform" novalidate>
     <label>${T(['Correo electrónico','E-mail'])}<input name="email" type="email" required autocomplete="email" placeholder="${T(['tu@correo.com','toi@email.com'])}"></label>
     <input name="website" tabindex="-1" autocomplete="off" class="hp" aria-hidden="true">
     <label class="check"><input type="checkbox" name="consent" required> <span>${T([`Acepto la <a href="${pv}">política de privacidad</a> y recibir información sobre el Club.`,`J'accepte la <a href="${pv}">politique de confidentialité</a> et de recevoir des infos sur le Club.`])}</span></label>
     <p class="lerr" hidden></p><button class="btn ghost" type="submit">${T(['Enviadme información','Envoyez-moi des infos'])}</button></form>
    <div class="lok panel" id="clubok" hidden></div></section>
   <section class="sec faq"><h2>${T(['Preguntas frecuentes','Questions fréquentes'])}</h2>${faq.map(f=>`<details><summary>${T(f[0])}</summary><p>${T(f[1])}</p></details>`).join('')}</section>${ld(faqLd(faq))}${ld({'@context':'https://schema.org','@type':'Product',name:'Club Ruta Suiza',description:T(['Una persona que trabaja en la administración suiza te explica tus cartas oficiales en español. Suscripción mensual sin permanencia.','Une personne qui travaille dans l\'administration suisse t\'explique tes courriers officiels en espagnol. Abonnement mensuel sans engagement.']),brand:{'@type':'Brand',name:'Ruta Suiza'},offers:{'@type':'Offer',price:'9.99',priceCurrency:'CHF',availability:'https://schema.org/InStock',url:SITE+'/'+LANG+'/club'}})}`;
}
function vPrecios(){
  const plan=(feat,name,price,per,items,cta,act)=>`<div class="plan ${feat?'feat':''}">${feat?`<span class="tag red">${T(['Recomendado','Recommandé'])}</span>`:''}<h3>${T(name)}</h3><div class="price">${price} <small>${T(per)}</small></div><ul>${items.map(i=>`<li>${T(i)}</li>`).join('')}</ul>${act==='club'?clubBtn():act==='buy'?`<button class="btn buy">${T(cta)}</button><small class="paynote">${T(['Tarjeta, Apple Pay o Google Pay · pago seguro con Stripe','Carte, Apple Pay ou Google Pay · paiement sécurisé par Stripe'])}</small>`:`<a class="btn ghost" href="#${act}">${T(cta)}</a>`}</div>`;
  return `<div class="article"><div class="eyebrow">${T(['Precios','Tarifs'])}</div><h1>${T(['Gratis para entender. El Club para no volver a estar solo.','Gratuit pour comprendre. Le Club pour ne plus jamais être seul·e.'])}</h1><p class="lead">${T(['Todas las guías y tu ruta son gratis. El Club te acompaña en el día a día por CHF 9.99 al mes, y la asesoría privada está ahí cuando necesitas preparar un expediente.','Tous les guides et ton parcours sont gratuits. Le Club t\'accompagne au quotidien pour CHF 9.99 par mois, et l\'accompagnement privé est là quand tu dois préparer un dossier.'])}</p></div>
  <div class="plans">
   ${plan(false,['Gratis','Gratuit'],'CHF 0',['para siempre','pour toujours'],[['Todas las guías y fichas por país','Tous les guides et fiches pays'],['Tu ruta personalizada (pasos y documentos)','Ton parcours personnalisé (étapes et documents)'],['Enlaces oficiales verificados','Liens officiels vérifiés']],['Empezar','Commencer'],'ruta')}
   ${plan(false,['Asesoría privada · 30 minutos','Accompagnement privé · 30 minutes'],'CHF 39',['pago único · 30 min','paiement unique · 30 min'],[['Conversación privada con una persona del equipo (videollamada o WhatsApp)','Échange privé avec une personne de l\'équipe (visio ou WhatsApp)'],['Te dice exactamente qué documentos necesitas y en qué orden','On te dit exactement quels documents il te faut et dans quel ordre'],['Tu plan por escrito con fechas y recordatorios','Ton plan écrit, daté, avec rappels'],['Formularios del cantón y plantillas','Formulaires du canton et modèles'],['Revisión de tu expediente antes de enviarlo','Relecture de ton dossier avant l\'envoi'],['Garantía: si falta un documento en tu plan, te devolvemos el dinero','Garantie : s\'il manque un document dans ton plan, on te rembourse']],['Pagar y reservar mi cita','Payer et réserver mon rendez-vous'],'buy')}
   ${plan(true,['Club Ruta Suiza','Club Ruta Suiza'],CLUB_PRICE,UI.month,CLUB_BEN.map(b=>{const x='<b>'+T(b[1])+'</b> — '+T(b[2]).split('. ')[0].replace(/\.$/,'');return [x,x];}),['',''],'club')}
  </div>
  <div class="sec">${helpBanner()}</div>
  <div class="sec article faq"><h2>${T(['Preguntas frecuentes','Questions fréquentes'])}</h2>
   ${[[['¿Quién está detrás?','Qui est derrière ?'],['Un equipo que habla español y francés y conoce la administración suiza desde dentro. Cada conversación privada es con una persona real, no con un robot.','Une équipe qui parle espagnol et français et connaît l\'administration suisse de l\'intérieur. Chaque échange privé se fait avec une vraie personne, pas un robot.']],
     [['¿Y si mi caso es complicado?','Et si mon cas est compliqué ?'],['Justamente para eso está la conversación privada. Si tu caso necesita un abogado (recurso, rechazo, caso judicial), te lo decimos y te orientamos.','C\'est justement à ça que sert l\'échange privé. Si ton cas demande un avocat (recours, refus, procédure), on te le dit et on t\'oriente.']],
     [['¿Cómo pago?','Comment je paie ?'],['Tarjeta (también Apple Pay o Google Pay), pago único. Sin suscripción obligatoria.','Carte (aussi Apple Pay ou Google Pay), paiement unique. Sans abonnement obligatoire.']],
     [['¿Qué pasa con mis datos?','Que deviennent mes données ?'],['Se alojan en Suiza, solo los usa el equipo para tu caso y no se venden nunca.','Elles sont hébergées en Suisse, utilisées seulement par l\'équipe pour ton dossier et jamais vendues.']],
     [['¿Es asesoría jurídica?','Est-ce un conseil juridique ?'],['No: es información y acompañamiento administrativo. Te ayudamos a preparar bien tu expediente; las decisiones las toman las autoridades.','Non : c\'est de l\'information et de l\'accompagnement administratif. On t\'aide à bien préparer ton dossier ; les décisions appartiennent aux autorités.']]]
     .map(q=>`<details><summary>${T(q[0])}</summary><p>${T(q[1])}</p></details>`).join('')}</div>${ld({'@context':'https://schema.org','@type':'OfferCatalog',name:T(['Precios Ruta Suiza','Tarifs Ruta Suiza']),itemListElement:[{'@type':'Offer',name:T(['Asesoría privada de 30 minutos','Accompagnement privé de 30 minutes']),price:'39',priceCurrency:'CHF',url:SITE+'/'+LANG+'/precios'},{'@type':'Offer',name:'Club Ruta Suiza',price:'9.99',priceCurrency:'CHF',url:SITE+'/'+LANG+'/club'}]})}`;
}

/* ---------- tool ---------- */
function route(){
  const co=C[S.country], ca=CANTONS.find(x=>x.k===S.canton);
  const eu=co.eu||S.dual, m=S.motive, city=T(ca.city), off=T(ca.office), cn=T(co.n), can=T(ca.n);
  const arrive={t:[`Anunciarte en tu comuna (${city} u otra)`,`T'annoncer à ta commune (${city} ou autre)`],p:['Declaras tu llegada en el control de habitantes. Es lo que activa tu permiso.','Tu déclares ton arrivée au contrôle des habitants. C\'est ce qui lance ton permis.'],w:['14 días','14 jours'],g:'comuna'};
  const lamal={t:['Seguro médico obligatorio (LAMal)','Assurance maladie obligatoire (LAMal)'],p:['Eliges una aseguradora. Según tus ingresos, puedes tener un subsidio del cantón.','Tu choisis un assureur. Selon tes revenus, tu peux avoir un subside du canton.'],w:['3 meses','3 mois'],g:'lamal'};
  let permit,steps,docs,head,sub;
  const D=k=>{const d=co.docs.find(x=>x.k===k);return {t:d.t,f:d.who,link:`#pais-${S.country}`};};
  const gen=(t,f,link)=>({t,f,link});
  if(m==='vivo'){
    permit='B / C / L / F';
    head=[`Ya estás en ${can}. Te ayudamos con lo del día a día.`,`Tu es déjà dans le canton de ${can}. On t'aide au quotidien.`];
    sub=['Cartas oficiales, impuestos, seguro, renovaciones: lo que más cuesta cuando ya estás instalado.','Courriers officiels, impôts, assurance, renouvellements : ce qui coûte le plus une fois installé.'];
    steps=[{t:['Entender tus cartas oficiales','Comprendre tes courriers officiels'],p:['Qué dicen, qué hacer y para cuándo.','Ce qu\'ils disent, quoi faire et pour quand.'],w:['Cada semana','Chaque semaine']},
      {t:['Subsidio del seguro médico','Subside d\'assurance maladie'],p:[`En ${can} puedes pedir una reducción de tu prima.`,`Dans le canton de ${can}, tu peux demander une réduction de prime.`],w:['Cada año','Chaque année'],g:'subsidio'},
      {t:['Impuesto en la fuente','Impôt à la source'],p:['Cuándo te conviene pedir la tasación ordinaria.','Quand demander la taxation ordinaire ultérieure.'],w:['Antes del 31 de marzo','Avant le 31 mars'],g:'impuestos'},
      {t:['Renovar tu permiso','Renouveler ton permis'],p:['Antes de que venza, en tu comuna.','Avant l\'échéance, auprès de ta commune.'],w:['Antes del vencimiento','Avant l\'échéance'],g:'permisos'},
      {t:['Traer a tu familia','Faire venir ta famille'],p:['Condiciones y plazos de la reagrupación.','Conditions et délais du regroupement.'],w:['Con plazos','Avec délais'],g:'familia'}];
    docs=[gen(['Tu permiso de residencia','Ton titre de séjour'],['Tarjeta B, C, L o F vigente','Carte B, C, L ou F valable'],'#guia-permisos'),gen(['Certificado de salario','Certificat de salaire'],['Lo da tu empleador cada año','Fourni par ton employeur chaque année'],'#guia-impuestos'),gen(['Póliza LAMal','Police LAMal'],['Tu contrato de seguro médico','Ton contrat d\'assurance maladie'],'#guia-lamal')];
  } else if(eu){
    permit={trabajo:'B / L',estudios:['B estudiante','B étudiant'],familia:['B reagrupación','B regroupement'],pareja:['B reagrupación','B regroupement']}[m];
    head=[`Con pasaporte europeo, vienes a ${can} con libre circulación.`,`Avec un passeport européen, tu viens dans le canton de ${can} en libre circulation.`];
    sub=['Sin visa. Tu camino es corto: lo esencial pasa en tu comuna.','Pas de visa. Ton parcours est court : l\'essentiel se passe à ta commune.'];
    const first={trabajo:{t:['Conseguir tu contrato','Obtenir ton contrat'],p:['Contrato de 1 año o más: permiso B. Menos: permiso L.','Contrat d\'un an ou plus : permis B. Moins : permis L.'],w:['Antes de venir','Avant de venir'],g:'permisos'},estudios:{t:['Carta de admisión','Attestation d\'admission'],p:['De la escuela o universidad, más prueba de medios financieros.','De l\'école ou université, avec preuve de moyens financiers.'],w:['Antes de venir','Avant de venir']},familia:{t:['Tu familiar en Suiza','Ton proche en Suisse'],p:['Necesita permiso válido y vivienda adecuada.','Il lui faut un permis valable et un logement approprié.'],w:['Antes de venir','Avant de venir'],g:'familia'},pareja:{t:['Matrimonio o unión registrada','Mariage ou partenariat enregistré'],p:['La reagrupación se basa en el vínculo oficial.','Le regroupement repose sur le lien officiel.'],w:['Antes de venir','Avant de venir'],g:'familia'}}[m];
    steps=[first,{t:['Entrar en Suiza','Entrer en Suisse'],p:['Con DNI o pasaporte europeo, sin visa.','Avec carte d\'identité ou passeport européen, sans visa.'],w:['Día 1','Jour 1']},arrive,lamal,{t:['Recibir tu permiso','Recevoir ton permis'],p:['Llega por correo a tu dirección suiza.','Il arrive par courrier à ton adresse suisse.'],w:['Algunas semanas','Quelques semaines'],g:'permisos'}];
    docs=[gen(['Pasaporte o DNI europeo','Passeport ou carte d\'identité européenne'],['Válido toda la estancia','Valable tout le séjour'],'#pais-es'),gen(['Contrato / admisión / vínculo familiar','Contrat / admission / lien familial'],['Según tu motivo','Selon ton motif'],'#guia-comuna'),gen(['Prueba de alojamiento','Preuve de logement'],['Contrato de alquiler o carta de quien te aloja','Bail ou attestation d\'hébergement'],'#guia-comuna')];
    if(m!=='trabajo'&&m!=='estudios') docs.push(Object.assign(D('birth'),{link:'#pais-'+(co.eu?'es':S.country)}));
  } else {
    permit={trabajo:['B con autorización (cupos)','B avec autorisation (contingents)'],estudios:['B estudiante','B étudiant'],familia:['B reagrupación','B regroupement'],pareja:['B reagrupación','B regroupement']}[m];
    head=[`Desde ${cn} a ${can}: tu camino es claro, y se puede.`,`De ${cn} au canton de ${can} : ton parcours est clair, et c'est possible.`];
    sub=[entryText(co),entryText(co)];
    const first={trabajo:[{t:['Un empleador que te contrate','Un employeur qui t\'engage'],p:['Él pide tu autorización. Perfiles cualificados y cupos anuales.','C\'est lui qui demande ton autorisation. Profils qualifiés et contingents annuels.'],w:['Antes de venir','Avant de venir'],g:'visa'},{t:['Aprobación del cantón y de la SEM',"Approbation du canton et du SEM"],p:[`El ${off} y luego la Confederación revisan tu caso.`,`Le ${off} puis la Confédération examinent ton dossier.`],w:['Varias semanas','Plusieurs semaines']}],
      estudios:[{t:['Carta de admisión','Attestation d\'admission'],p:['De una escuela reconocida, que suele seguir tu solicitud.','D\'une école reconnue, qui suit souvent ta demande.'],w:['Antes de venir','Avant de venir']},{t:['Medios financieros','Moyens financiers'],p:['Prueba que puedes vivir durante tus estudios.','Preuve que tu peux vivre pendant tes études.'],w:['Antes de la visa','Avant le visa']}],
      familia:[{t:['Tu familiar presenta la solicitud','Ton proche dépose la demande'],p:['Necesita permiso B o C, vivienda adecuada y no depender de la ayuda social.','Il lui faut un permis B ou C, un logement approprié et ne pas dépendre de l\'aide sociale.'],w:['Antes de venir','Avant de venir'],g:'familia'},{t:[`Revisión por el ${off}`,`Examen par le ${off}`],p:['El cantón examina la reagrupación.','Le canton examine le regroupement.'],w:['Varias semanas','Plusieurs semaines']}],
      pareja:[{t:['Matrimonio o unión registrada','Mariage ou partenariat enregistré'],p:['Sin vínculo oficial hay otras vías: tu caso merece revisión humana.','Sans lien officiel, d\'autres voies existent : ton cas mérite une analyse humaine.'],w:['Antes de venir','Avant de venir'],g:'familia'},{t:[`Solicitud ante el ${off}`,`Demande auprès du ${off}`],p:['Tu pareja en Suiza presenta la solicitud.','Ton/ta partenaire en Suisse dépose la demande.'],w:['Varias semanas','Plusieurs semaines']}]}[m];
    steps=[...first,{t:['Visa nacional D','Visa national D'],p:[`En la representación suiza competente para ${cn}.`,`Auprès de la représentation suisse compétente pour ${cn}.`],w:['Tras la aprobación','Après l\'approbation'],g:'visa'},arrive,lamal,{t:['Recibir tu permiso B','Recevoir ton permis B'],p:['Llega por correo a tu dirección suiza.','Il arrive par courrier à ton adresse suisse.'],w:['Algunas semanas','Quelques semaines'],g:'permisos'}];
    docs=[gen(['Pasaporte vigente','Passeport valable'],['3 meses más que tu estancia, páginas libres','3 mois de plus que le séjour, pages libres'],`#pais-${S.country}`),D('birth'),D('crim')];
    const extra={trabajo:[gen(['Contrato de trabajo','Contrat de travail'],['Firmado por el empleador suizo','Signé par l\'employeur suisse'],'#guia-visa'),gen(['Diplomas apostillados','Diplômes apostillés'],['Y CV','Avec CV'],`#pais-${S.country}`)],estudios:[gen(['Carta de admisión','Attestation d\'admission'],['De la escuela','De l\'école'],'#guia-visa'),gen(['Prueba de medios financieros','Preuve de moyens financiers'],['Cuenta, beca o garantía','Compte, bourse ou garantie'],'#guia-visa')],familia:[gen(['Acta de matrimonio / nacimiento de los hijos','Acte de mariage / naissance des enfants'],['Apostillada y traducida','Apostillé et traduit'],'#guia-familia')],pareja:[gen(['Acta de matrimonio o unión','Acte de mariage ou partenariat'],['Apostillada y traducida','Apostillé et traduit'],'#guia-familia')]}[m];
    docs.push(...extra,gen(['Prueba de alojamiento','Preuve de logement'],['Contrato o carta de alojamiento','Bail ou attestation d\'hébergement'],'#guia-comuna'));
  }
  return {co,ca,eu,permit:T(permit),steps,docs,head:T(head),sub:T(sub),city,off,cn,can};
}
function vRuta(){
  return `<h1 class="tool-h1">${T(['Calcula tu ruta a Suiza','Calcule ton parcours vers la Suisse'])}</h1><div class="tool"><aside class="panel picker" aria-label="Perfil">
    <div class="q"><h2><span class="n">1</span>${T(['¿De dónde eres?','D\'où viens-tu ?'])}</h2><div class="chips" id="t-c">${ORDER.map(k=>`<button class="chip" data-v="${k}" aria-pressed="${S.country===k}"><span class="cc">${k.toUpperCase()}</span>${T(C[k].n)}</button>`).join('')}</div>
      ${S.country!=='es'?`<label class="check" for="dual"><input type="checkbox" id="dual" ${S.dual?'checked':''}> ${T(['Tengo también pasaporte europeo','J\'ai aussi un passeport européen'])}</label>`:''}</div>
    <div class="q"><h2><span class="n">2</span>${T(['¿Por qué vienes?','Pourquoi viens-tu ?'])}</h2><div class="chips" id="t-m">${MOTIVES.map(x=>`<button class="chip" data-v="${x.k}" aria-pressed="${S.motive===x.k}">${T(x.n)}</button>`).join('')}</div></div>
    <div class="q"><h2><span class="n">3</span>${T(['¿Qué cantón?','Quel canton ?'])}</h2><div class="chips" id="t-k">${CANTONS.map(x=>`<button class="chip" data-v="${x.k}" aria-pressed="${S.canton===x.k}">${T(x.n)}</button>`).join('')}</div></div>
  </aside><section class="result" id="res" aria-live="polite">${resultHTML()}</section></div>`;
}
function resultHTML(){
  const r=route();
  return `<div class="panel profile"><div class="pills"><span class="pill">${r.cn}${S.dual&&S.country!=='es'?' + UE':''}</span><span class="pill">${r.can}</span><span class="pill ${r.eu?'ok':'warn'}">${r.eu?T(['Libre circulación UE','Libre circulation UE']):T(['Fuera de la UE','Hors UE'])}</span><span class="pill ok">${T(['Permiso','Permis'])} ${r.permit}</span></div>
    <h2>${r.head}</h2><p>${r.sub}</p><div class="meter"><div class="track"><i></i></div><small>${T(['Ya conoces el 80 % de tu camino. Lo que falta es el plan para pasar a la acción.','Tu connais déjà 80 % de ton parcours. Il te manque le plan pour passer à l\'action.'])}</small></div></div>
  <div class="panel"><div class="sec-h"><h3>${T(['Tu camino','Ton parcours'])}</h3><span>${T(['Gratis · completo','Gratuit · complet'])}</span></div><ol class="steps">${r.steps.map((s,i)=>`<li><span class="sn">${i+1}</span><div class="st"><b>${T(s.t)}</b><p>${T(s.p)}${s.g?` <a href="#guia-${s.g}">${T(['Guía','Guide'])} →</a>`:''}</p><span class="when">${T(s.w)}</span></div></li>`).join('')}</ol></div>
  <div class="panel"><div class="sec-h"><h3>${T(['Tus documentos','Tes documents'])}</h3><span>${r.docs.length} ${T(['documentos · explicados','documents · expliqués'])}</span></div><div class="docs">${r.docs.map(d=>`<div class="doc"><span class="tick">✓</span><span><b>${T(d.t)}</b><small>${T(d.f)}</small></span><a href="${d.link}">${T(UI.howto)} →</a></div>`).join('')}</div>
</div>
  ${planPreview(r)}
  ${riskBlock(r)}
  <div class="panel dream"><h3>${T([`Imagínate dentro de unos meses en ${r.city}.`,`Imagine-toi dans quelques mois à ${r.city}.`])}</h3><p>${T(['Con tu permiso en mano, tu seguro al día y tus cartas bajo control. El camino existe, y ahora lo conoces.','Avec ton permis en main, ton assurance en ordre et tes courriers sous contrôle. Le chemin existe, et maintenant tu le connais.'])}</p>
    <div class="g3"><div class="g"><b>${r.steps.length} ${T(['pasos','étapes'])}</b><small>${T(['de aquí a tu permiso','d\'ici à ton permis'])}</small></div><div class="g"><b>${r.docs.length} ${T(['documentos','documents'])}</b><small>${T(['ya identificados','déjà identifiés'])}</small></div><div class="g"><b>${T(['Personas reales','Vraies personnes'])}</b><small>${T(['detrás de tu expediente','derrière ton dossier'])}</small></div></div></div>
  ${offerBlock(r)}`;
}
