function helpBanner(compact){
  return `<div class="panel help ${compact?'cmp':''}"><div><h3>${T(['¿Todo esto te parece complicado?','Tout ça te semble compliqué ?'])}</h3>
   <p>${T(['Habla en privado con una persona de nuestro equipo. Te dice exactamente qué documentos necesitas, dónde pedirlos y en qué orden, en español.','Parle en privé à une personne de notre équipe. Elle te dit exactement quels documents il te faut, où les demander et dans quel ordre, en espagnol ou en français.'])}</p></div>
   <div class="hb"><button class="btn unlock">${T(['Hablar con una persona','Parler à une personne'])}</button><button class="btn ghost ask">${T(['Pregunta gratis','Question gratuite'])}</button></div></div>`;
}
function mondayPlus(weeks){const d=new Date();const day=(d.getDay()+6)%7;d.setDate(d.getDate()-day+7+weeks*7);return d.toLocaleDateString(LANG==='es'?'es-ES':'fr-CH',{day:'numeric',month:'short'});}
function planItems(r){
  const crim=r.co.docs.find(d=>d.k==='crim'), birth=r.co.docs.find(d=>d.k==='birth');
  const wk=n=>T(['Semana del ','Semaine du '])+mondayPlus(n);
  if(S.motive==='vivo') return [
    [T(['Este mes','Ce mois-ci']),['Pedir el subsidio LAMal de tu cantón','Demander le subside LAMal de ton canton'],[`Formulario de ${r.can} prellenado con tus datos.`,`Formulaire du canton de ${r.can} prérempli avec tes données.`]],
    [T(['Este mes','Ce mois-ci']),['Revisar tus primas y franquicia','Revoir tes primes et ta franchise'],['Comparación con tu consumo real.','Comparaison avec ta consommation réelle.']],
    [T(['Antes del 31 de marzo','Avant le 31 mars']),['Decidir la tasación ordinaria','Décider de la taxation ordinaire'],['Cálculo: ¿te conviene o no?','Calcul : est-ce que ça vaut le coup ?']],
    [T(['3 meses antes','3 mois avant']),['Renovar tu permiso','Renouveler ton permis'],['Recordatorio automático + documentos.','Rappel automatique + documents.']],
    [T(['Cuando quieras','Quand tu veux']),['Preparar el permiso C','Préparer le permis C'],['Años, idioma, integración: tu checklist.','Années, langue, intégration : ta checklist.']]];
  if(r.eu) return [
    [wk(0),['Reunir contrato o admisión','Réunir contrat ou admission'],['Qué debe decir para un permiso B y no un L.','Ce qu\'il doit indiquer pour un permis B et non L.']],
    [wk(0),['Preparar la prueba de alojamiento','Préparer la preuve de logement'],['Modelo de carta de alojamiento incluido.','Modèle d\'attestation d\'hébergement inclus.']],
    [T(['Día de llegada','Jour d\'arrivée']),['Anunciarte en tu comuna','T\'annoncer à ta commune'],[`Lista exacta de ${r.city}, horarios y dirección.`,`Liste exacte de ${r.city}, horaires et adresse.`]],
    [T(['Antes de 3 meses','Avant 3 mois']),['Elegir tu seguro LAMal','Choisir ton assurance LAMal'],['Franquicia y modelo adaptados a ti.','Franchise et modèle adaptés à toi.']],
    [T(['Primer salario','Premier salaire']),['Revisar tu impuesto en la fuente','Vérifier ton impôt à la source'],['Que tu barema sea el correcto.','Que ton barème soit le bon.']]];
  return [
    [wk(0),[`Pedir: ${T(crim.t)}`,`Demander : ${T(crim.t)}`],[`${T(crim.who)}. ${T(crim.how)}`,`${T(crim.who)}. ${T(crim.how)}`]],
    [wk(0),[`Pedir: ${T(birth.t)}`,`Demander : ${T(birth.t)}`],[T(birth.how),T(birth.how)]],
    [wk(1),[r.co.hague?'Apostillar los dos documentos':'Legalizar los dos documentos',r.co.hague?'Faire apostiller les deux documents':'Faire légaliser les deux documents'],['Enlace directo, costo y plazo para tu país.','Lien direct, coût et délai pour ton pays.']],
    [wk(2),['Traducción oficial al francés','Traduction officielle en français'],['Documento + apostilla, con traductor socio.','Document + apostille, avec un traducteur partenaire.']],
    [wk(3),[`Enviar el expediente para el ${r.off}`,`Envoyer le dossier pour le ${r.off}`],['Checklist del cantón, revisada por el equipo.','Checklist du canton, relue par l\'équipe.']],
    [T(['Tras la aprobación','Après l\'approbation']),['Cita para la visa D','Rendez-vous pour le visa D'],[`Representación suiza para ${r.cn}.`,`Représentation suisse pour ${r.cn}.`]],
    [T(['Llegada + 14 días','Arrivée + 14 jours']),['Comuna y seguro LAMal','Commune et assurance LAMal'],[`Lista exacta de ${r.city}.`,`Liste exacte de ${r.city}.`]]];
}
function planPreview(r){
  const items=planItems(r);
  const row=(it,i,lock)=>`<div class="prow2 ${lock?'lk':''}"><span class="wk">${it[0]}</span><div><b>${T(it[1])}</b><small>${T(it[2])}</small></div><span class="st2">${lock?LOCK:CHECK}</span></div>`;
  return `<div class="panel planp"><div class="sec-h"><h3>${T(['Tu plan con fechas','Ton plan daté'])}</h3><span>${T(['Vista previa · 2 de ','Aperçu · 2 sur '])}${items.length}</span></div>
   <p class="muted" style="margin:-6px 0 14px;font-size:15px">${T([`Calculado para ${r.cn} → ${r.can}, empezando la próxima semana.`,`Calculé pour ${r.cn} → ${r.can}, à partir de la semaine prochaine.`])}</p>
   <div class="prows">${items.map((it,i)=>row(it,i,i>1)).join('')}
     <div class="fade"><button class="btn unlock">${LOCK} ${T(['Recibir mi plan completo con una persona','Recevoir mon plan complet avec une personne'])}</button></div></div></div>`;
}
function riskBlock(r){
  const crim=r.co.docs.find(d=>d.k==='crim');
  const items=S.motive==='vivo'?[
    [['No pedir el subsidio LAMal','Ne pas demander le subside LAMal'],['Muchas personas con derecho no lo piden y pagan la prima entera.','Beaucoup de personnes y ont droit sans le demander et paient la prime entière.']],
    [['Dejar pasar el plazo de la tasación','Laisser passer le délai de taxation'],['Después del plazo ya no puedes deducir tus gastos de ese año.','Après le délai, tu ne peux plus déduire tes frais de l\'année.']],
    [['Renovar el permiso tarde','Renouveler le permis en retard'],['Un permiso vencido complica el trabajo, la vivienda y los viajes.','Un permis échu complique le travail, le logement et les voyages.']]]
   : r.eu?[
    [['Pasar los 14 días sin anunciarte','Dépasser les 14 jours sans t\'annoncer'],['Debes anunciarte antes de empezar a trabajar.','Tu dois t\'annoncer avant de commencer à travailler.']],
    [['Olvidar el seguro LAMal','Oublier l\'assurance LAMal'],['Pasados 3 meses, te afilian de oficio y puede haber recargo.','Après 3 mois, on t\'affilie d\'office et un supplément peut s\'appliquer.']],
    [['Traducir antes de apostillar','Traduire avant d\'apostiller'],['La apostilla queda sin traducir y hay que repetir.','L\'apostille n\'est pas traduite et il faut tout refaire.']]]
   :[
    [['Pedir el certificado penal demasiado pronto',"Demander le casier judiciaire trop tôt"],[`Validez: ${T(crim.valid)} Si caduca antes de tu cita, vuelves a empezar.`,`Validité : ${T(crim.valid)} S'il expire avant ton rendez-vous, tu recommences.`]],
    [['Traducir antes de apostillar','Traduire avant d\'apostiller'],['La apostilla queda sin traducir: nueva traducción, nuevo pago.','L\'apostille n\'est pas traduite : nouvelle traduction, nouveau paiement.']],
    [['Venir como turista y «arreglar después»','Venir en touriste et « régulariser après »'],['Sin visa D aprobada por el cantón, no hay permiso.','Sans visa D approuvé par le canton, pas de permis.']]];
  return `<div class="panel risk"><h3>${T(['Los 3 errores que más retrasan un expediente como el tuyo','Les 3 erreurs qui retardent le plus un dossier comme le tien'])}</h3>
   <ol>${items.map(x=>`<li><b>${T(x[0])}</b><span>${T(x[1])}</span></li>`).join('')}</ol>
   <p class="muted" style="margin:10px 0 0;font-size:14px">${T(['Cada error significa volver a pedir, apostillar y traducir: semanas perdidas y dinero gastado dos veces.','Chaque erreur, c\'est redemander, réapostiller et retraduire : des semaines perdues et de l\'argent dépensé deux fois.'])}</p></div>`;
}
function offerBlock(r){
  const stack=[
    [['Una conversación privada, en español','Un échange privé, en espagnol'],['Por videollamada o WhatsApp, con una persona de nuestro equipo que conoce la administración suiza.','En visio ou sur WhatsApp, avec une personne de l\'équipe qui connaît l\'administration suisse.']],
    [['Te dice exactamente qué necesitas','On te dit exactement ce qu\'il te faut'],[`Revisa tu caso (${r.cn} → ${r.can}) y te dice qué documentos pedir, dónde y en qué orden.`,`On regarde ton cas (${r.cn} → ${r.can}) et on te dit quels documents demander, où et dans quel ordre.`]],
    [['Tu plan por escrito, con fechas','Ton plan écrit, daté'],['Lo recibes después de la conversación, con enlaces directos y recordatorios.','Tu le reçois après l\'échange, avec liens directs et rappels.']],
    [['Formularios del cantón y plantillas','Formulaires du canton et modèles'],[`${r.off}: carta de alojamiento, motivación, reclamación.`,`${r.off} : attestation d'hébergement, lettre de motivation, réclamation.`]],
    [['Revisión de tu expediente antes de enviarlo','Relecture de ton dossier avant l\'envoi'],['Para que no te lo devuelvan por un detalle.','Pour qu\'on ne te le renvoie pas pour un détail.']]];
  return `<div class="panel offer">
   <div class="eyebrow">${T(['Asesoría privada','Accompagnement privé'])}</div>
   <h3>${T(['¿Todo esto te parece complicado? Habla en privado con una persona que te dice todo lo que necesitas.','Tout ça te semble compliqué ? Parle en privé à une personne qui te dira tout ce qu\'il te faut.'])}</h3>
   <ul class="stack">${stack.map(x=>`<li>${CHECK}<div><b>${T(x[0])}</b><small>${T(x[1])}</small></div></li>`).join('')}</ul>
   <div class="guar"><b>${T(['Garantía','Garantie'])}</b> ${T(['Si el cantón te pide un documento que no estaba en tu plan, te devolvemos los 39 CHF.','Si le canton te demande un document qui n\'était pas dans ton plan, on te rembourse les 39 CHF.'])}</div>
   <div class="prow"><div><span class="price">CHF 39</span> <small class="muted">${T(['pago único · tarjeta','paiement unique · carte'])}</small></div>
     <button class="btn unlock">${T(['Hablar con una persona','Parler à une personne'])}</button>
     <button class="btn ghost ask">${T(['Hacer una pregunta gratis','Poser une question gratuite'])}</button></div>
   <div class="trust"><span>${T(['Respuesta humana en 24–48 h','Réponse humaine en 24–48 h'])}</span><span>${T(['Tus datos no se venden','Tes données ne sont pas vendues'])}</span><span>${T(['Alojado en Suiza','Hébergé en Suisse'])}</span></div></div>`;
}

